                1 -> {
                    BoolVal(
                        reader.readBool()
                    )
                }
                2 -> {
                    ByteVal(
                        reader.readI8()
                    )
                }
                3 -> {
                    ShortVal(
                        reader.readI16()
                    )
                }
                4 -> {
                    CharVal(
                        reader.readU16()
                    )
                }
                5 -> {
                    IntVal(
                        reader.readI32()
                    )
                }
                6 -> {
                    LongVal(
                        reader.readI64()
                    )
                }
                7 -> {
                    FloatVal(
                        reader.readF32()
                    )
                }
                8 -> {
                    DoubleVal(
                        reader.readF64()
                    )
                }
                9 -> {
                    StringVal(
                        reader.readString()
                    )
                }
                10 -> {
                    TypeVal(
                        reader.readString()
                    )
                }
                else -> throw FfiException(-1, "Unknown EncodedVal tag: $tag")
            }
        }
    }

    fun wireEncodedSize(): Int = 4 + when (this) {
        is Null -> 0
        is BoolVal -> 1
        is ByteVal -> 1
        is ShortVal -> 2
        is CharVal -> 2
        is IntVal -> 4
        is LongVal -> 8
        is FloatVal -> 4
        is DoubleVal -> 8
        is StringVal -> (4 + Utf8Codec.maxBytes(value0))
        is TypeVal -> (4 + Utf8Codec.maxBytes(value0))
    }

    fun wireEncodeTo(wire: WireWriter) {
        when (this) {
            is Null -> wire.writeI32(0)
            is BoolVal -> {
                wire.writeI32(1)
                wire.writeBool(value0)
            }
            is ByteVal -> {
                wire.writeI32(2)
                wire.writeI8(value0)
            }
            is ShortVal -> {
                wire.writeI32(3)
                wire.writeI16(value0)
            }
            is CharVal -> {
                wire.writeI32(4)
                wire.writeU16(value0)
            }
            is IntVal -> {
                wire.writeI32(5)
                wire.writeI32(value0)
            }
            is LongVal -> {
                wire.writeI32(6)
                wire.writeI64(value0)
            }
            is FloatVal -> {
                wire.writeI32(7)
                wire.writeF32(value0)
            }
            is DoubleVal -> {
                wire.writeI32(8)
                wire.writeF64(value0)
            }
            is StringVal -> {
                wire.writeI32(9)
                wire.writeString(value0)
            }
            is TypeVal -> {
