                }
                5 -> {
                    RegString(
                        RegStringInsn.decode(reader)
                    )
                }
                6 -> {
                    RegType(
                        RegTypeInsn.decode(reader)
                    )
                }
                7 -> {
                    RegField(
                        RegFieldInsn.decode(reader)
                    )
                }
                8 -> {
                    Invoke(
                        InvokeInsn.decode(reader)
                    )
                }
                9 -> {
                    InvokeRange(
                        InvokeRangeInsn.decode(reader)
                    )
                }
                10 -> {
                    Branch0(
                        Branch0Insn.decode(reader)
                    )
                }
                11 -> {
                    Branch(
                        BranchInsn.decode(reader)
                    )
                }
                12 -> {
                    Branch2(
                        Branch2Insn.decode(reader)
                    )
                }
                13 -> {
                    FilledArray(
                        FilledArrayInsn.decode(reader)
                    )
                }
                14 -> {
                    FilledArrayRange(
                        FilledArrayRangeInsn.decode(reader)
                    )
                }
                15 -> {
                    PackedSwitchData(
                        PackedSwitchInsn.decode(reader)
                    )
                }
                16 -> {
                    SparseSwitchData(
                        SparseSwitchInsn.decode(reader)
                    )
                }
                17 -> {
                    FillArrayData(
                        FillArrayInsn.decode(reader)
                    )
                }
                18 -> {
                    Raw(
                        reader.readBytes()
                    )
                }
                else -> throw FfiException(-1, "Unknown Instruction tag: $tag")
            }
        }
    }

    fun wireEncodedSize(): Int = 4 + when (this) {
        is Simple -> 2
        is Reg1 -> 4
        is Reg2 -> 6
        is Reg3 -> 8
        is RegLiteral -> 16
        is RegString -> value0.wireEncodedSize()
        is RegType -> value0.wireEncodedSize()
        is RegField -> value0.wireEncodedSize()
        is Invoke -> value0.wireEncodedSize()
        is InvokeRange -> value0.wireEncodedSize()
        is Branch0 -> 8
        is Branch -> 8
        is Branch2 -> 12
        is FilledArray -> value0.wireEncodedSize()
        is FilledArrayRange -> value0.wireEncodedSize()
        is PackedSwitchData -> value0.wireEncodedSize()
        is SparseSwitchData -> value0.wireEncodedSize()
        is FillArrayData -> value0.wireEncodedSize()
        is Raw -> (4 + value0.size)
    }

    fun wireEncodeTo(wire: WireWriter) {
        when (this) {
            is Simple -> {
                wire.writeI32(0)
                value0.wireEncodeTo(wire)
            }
            is Reg1 -> {
                wire.writeI32(1)
                value0.wireEncodeTo(wire)
            }
            is Reg2 -> {
                wire.writeI32(2)
                value0.wireEncodeTo(wire)
            }
            is Reg3 -> {
                wire.writeI32(3)
                value0.wireEncodeTo(wire)
            }
            is RegLiteral -> {
                wire.writeI32(4)
                value0.wireEncodeTo(wire)
            }
            is RegString -> {
                wire.writeI32(5)
                value0.wireEncodeTo(wire)
            }
            is RegType -> {
                wire.writeI32(6)
                value0.wireEncodeTo(wire)
            }
            is RegField -> {
                wire.writeI32(7)
                value0.wireEncodeTo(wire)
            }
            is Invoke -> {
                wire.writeI32(8)
                value0.wireEncodeTo(wire)
            }
            is InvokeRange -> {
                wire.writeI32(9)
                value0.wireEncodeTo(wire)
            }
            is Branch0 -> {
                wire.writeI32(10)
                value0.wireEncodeTo(wire)
            }
            is Branch -> {
                wire.writeI32(11)
                value0.wireEncodeTo(wire)
            }
            is Branch2 -> {
                wire.writeI32(12)
                value0.wireEncodeTo(wire)
            }
            is FilledArray -> {
                wire.writeI32(13)
                value0.wireEncodeTo(wire)
            }
            is FilledArrayRange -> {
                wire.writeI32(14)
                value0.wireEncodeTo(wire)
            }
            is PackedSwitchData -> {
                wire.writeI32(15)
                value0.wireEncodeTo(wire)
            }
            is SparseSwitchData -> {
                wire.writeI32(16)
                value0.wireEncodeTo(wire)
            }
            is FillArrayData -> {
                wire.writeI32(17)
                value0.wireEncodeTo(wire)
            }
            is Raw -> {
                wire.writeI32(18)
                wire.writePrimitiveList(value0)
            }
        }
    }
}

data class MethodInfo(
    val classDescriptor: String,
    val methodName: String,
    val proto: String,
    val accessFlags: UInt,
    val dexIndex: UInt,
    val registerCount: UShort,
    val insSize: UShort,
    val outsSize: UShort,
    val instructionCount: UInt
) {
    companion object {
        fun decode(reader: WireReader): MethodInfo = MethodInfo(
            reader.readString(),
            reader.readString(),
            reader.readString(),
            reader.readU32(),
            reader.readU32(),
            reader.readU16(),
            reader.readU16(),
            reader.readU16(),
            reader.readU32()
        )
    }
    fun wireEncodedSize(): Int =
        (4 + Utf8Codec.maxBytes(classDescriptor)) +
        (4 + Utf8Codec.maxBytes(methodName)) +
        (4 + Utf8Codec.maxBytes(proto)) +
        4 +
        4 +
        2 +
        2 +
        2 +
        4

    fun wireEncodeTo(wire: WireWriter) {
        wire.writeString(classDescriptor)
        wire.writeString(methodName)
        wire.writeString(proto)
        wire.writeU32(accessFlags)
        wire.writeU32(dexIndex)
        wire.writeU16(registerCount)
        wire.writeU16(insSize)
        wire.writeU16(outsSize)
        wire.writeU32(instructionCount)
    }
}

data class ClassInfo(
    val descriptor: String,
    val accessFlags: UInt,
    val superclass: String? = null,
    val interfaces: List<String>,
    val sourceFile: String? = null,
    val dexIndex: UInt,
    val directMethodCount: UInt,
    val virtualMethodCount: UInt,
    val staticFieldCount: UInt,
    val instanceFieldCount: UInt
) {
    companion object {
        fun decode(reader: WireReader): ClassInfo = ClassInfo(
            reader.readString(),
            reader.readU32(),
            reader.readOptional { reader.readString() },
            reader.readList { reader.readString() },
            reader.readOptional { reader.readString() },
            reader.readU32(),
            reader.readU32(),
            reader.readU32(),
            reader.readU32(),
            reader.readU32()
        )
    }
    fun wireEncodedSize(): Int =
        (4 + Utf8Codec.maxBytes(descriptor)) +
        4 +
        (superclass?.let { v -> 1 + (4 + Utf8Codec.maxBytes(v)) } ?: 1.toInt()) +
        (4 + interfaces.sumOf { item -> (4 + Utf8Codec.maxBytes(item)) }) +
        (sourceFile?.let { v -> 1 + (4 + Utf8Codec.maxBytes(v)) } ?: 1.toInt()) +
        4 +
        4 +
        4 +
        4 +
        4

    fun wireEncodeTo(wire: WireWriter) {
        wire.writeString(descriptor)
        wire.writeU32(accessFlags)
        superclass?.let { v -> wire.writeU8(1u); wire.writeString(v) } ?: wire.writeU8(0u)
        wire.writeU32(interfaces.size.toUInt()); interfaces.forEach { item -> wire.writeString(item) }
        sourceFile?.let { v -> wire.writeU8(1u); wire.writeString(v) } ?: wire.writeU8(0u)
        wire.writeU32(dexIndex)
        wire.writeU32(directMethodCount)
        wire.writeU32(virtualMethodCount)
        wire.writeU32(staticFieldCount)
        wire.writeU32(instanceFieldCount)
    }
}

data class FieldInfo(
    val classDescriptor: String,
    val name: String,
    val fieldType: String,
    val accessFlags: UInt,
    val initialValue: EncodedVal? = null
) {
    companion object {
        fun decode(reader: WireReader): FieldInfo = FieldInfo(
            reader.readString(),
            reader.readString(),
            reader.readString(),
            reader.readU32(),
            reader.readOptional { EncodedVal.decode(reader) }
        )
    }
    fun wireEncodedSize(): Int =
        (4 + Utf8Codec.maxBytes(classDescriptor)) +
        (4 + Utf8Codec.maxBytes(name)) +
        (4 + Utf8Codec.maxBytes(fieldType)) +
        4 +
        (initialValue?.let { v -> 1 + v.wireEncodedSize() } ?: 1.toInt())

    fun wireEncodeTo(wire: WireWriter) {
        wire.writeString(classDescriptor)
        wire.writeString(name)
        wire.writeString(fieldType)
        wire.writeU32(accessFlags)
        initialValue?.let { v -> wire.writeU8(1u); v.wireEncodeTo(wire) } ?: wire.writeU8(0u)
    }
}

data class FingerprintDef(
    val name: String? = null,
    val definingClass: String? = null,
    val accessFlags: UInt? = null,
    val returnType: String? = null,
    val parameters: List<String>? = null,
    val opcodes: IntArray? = null,
    val strings: List<String>? = null,
    val literals: LongArray? = null
) {
    companion object {
        fun decode(reader: WireReader): FingerprintDef = FingerprintDef(
            reader.readOptional { reader.readString() },
            reader.readOptional { reader.readString() },
            reader.readOptional { reader.readU32() },
            reader.readOptional { reader.readString() },
            reader.readOptional { reader.readList { reader.readString() } },
            reader.readOptional { reader.readIntArray() },
            reader.readOptional { reader.readList { reader.readString() } },
            reader.readOptional { reader.readLongArray() }
        )
    }
    fun wireEncodedSize(): Int =
        (name?.let { v -> 1 + (4 + Utf8Codec.maxBytes(v)) } ?: 1.toInt()) +
        (definingClass?.let { v -> 1 + (4 + Utf8Codec.maxBytes(v)) } ?: 1.toInt()) +
        (accessFlags?.let { v -> 1 + 4 } ?: 1.toInt()) +
        (returnType?.let { v -> 1 + (4 + Utf8Codec.maxBytes(v)) } ?: 1.toInt()) +
        (parameters?.let { v -> 1 + (4 + v.sumOf { item -> (4 + Utf8Codec.maxBytes(item)) }) } ?: 1.toInt()) +
        (opcodes?.let { v -> 1 + (4 + v.size * 4) } ?: 1.toInt()) +
        (strings?.let { v -> 1 + (4 + v.sumOf { item -> (4 + Utf8Codec.maxBytes(item)) }) } ?: 1.toInt()) +
        (literals?.let { v -> 1 + (4 + v.size * 8) } ?: 1.toInt())

    fun wireEncodeTo(wire: WireWriter) {
        name?.let { v -> wire.writeU8(1u); wire.writeString(v) } ?: wire.writeU8(0u)
        definingClass?.let { v -> wire.writeU8(1u); wire.writeString(v) } ?: wire.writeU8(0u)
        accessFlags?.let { v -> wire.writeU8(1u); wire.writeU32(v) } ?: wire.writeU8(0u)
        returnType?.let { v -> wire.writeU8(1u); wire.writeString(v) } ?: wire.writeU8(0u)
        parameters?.let { v -> wire.writeU8(1u); wire.writeU32(v.size.toUInt()); v.forEach { item -> wire.writeString(item) } } ?: wire.writeU8(0u)
        opcodes?.let { v -> wire.writeU8(1u); wire.writePrimitiveList(v) } ?: wire.writeU8(0u)
        strings?.let { v -> wire.writeU8(1u); wire.writeU32(v.size.toUInt()); v.forEach { item -> wire.writeString(item) } } ?: wire.writeU8(0u)
        literals?.let { v -> wire.writeU8(1u); wire.writePrimitiveList(v) } ?: wire.writeU8(0u)
    }
}

