data class NewMethod(
    val name: String,
    val proto: String,
    val accessFlags: UInt,
    val registersSize: UShort,
    val insSize: UShort,
    val outsSize: UShort,
    val instructions: List<Instruction>,
    val tries: List<TryItem>,
    val catchHandlers: List<CatchHandler>
) {
    companion object {
        fun decode(reader: WireReader): NewMethod = NewMethod(
            reader.readString(),
            reader.readString(),
            reader.readU32(),
            reader.readU16(),
            reader.readU16(),
            reader.readU16(),
            reader.readList { Instruction.decode(reader) },
            reader.readList { TryItem.decode(reader) },
            reader.readList { CatchHandler.decode(reader) }
        )
    }
    fun wireEncodedSize(): Int =
        (4 + Utf8Codec.maxBytes(name)) +
        (4 + Utf8Codec.maxBytes(proto)) +
        4 +
        2 +
        2 +
        2 +
        (4 + instructions.sumOf { item -> item.wireEncodedSize() }) +
        (4 + tries.size * 12) +
        (4 + catchHandlers.sumOf { item -> item.wireEncodedSize() })

    fun wireEncodeTo(wire: WireWriter) {
        wire.writeString(name)
        wire.writeString(proto)
        wire.writeU32(accessFlags)
        wire.writeU16(registersSize)
        wire.writeU16(insSize)
        wire.writeU16(outsSize)
        wire.writeU32(instructions.size.toUInt()); instructions.forEach { item -> item.wireEncodeTo(wire) }
        wire.writeU32(tries.size.toUInt()); TryItemWriter.writeAllToWire(wire, tries)
        wire.writeU32(catchHandlers.size.toUInt()); catchHandlers.forEach { item -> item.wireEncodeTo(wire) }
    }
}

data class TryItem(
    val startAddr: UInt,
    val insnCount: UShort,
