) {
    companion object {
        const val SIZE_BYTES: Int = 12

        fun decode(reader: WireReader): TryItem = TryItem(
            reader.readU32(),
            reader.readU16().also { reader.skip(2) },
            reader.readU32()
        )
    }
    fun wireEncodedSize(): Int = SIZE_BYTES

    fun wireEncodeTo(wire: WireWriter) {
        wire.writeU32(startAddr)
        wire.writeU16(insnCount)
        wire.writePadding(2)
        wire.writeU32(handlerIdx)
    }
}

data class CatchHandler(
    val typedCatches: List<TypedCatch>,
