            index = buf.getInt(offset + OFFSET_INDEX).toUInt(),
            targetIndex = buf.getInt(offset + OFFSET_TARGET_INDEX).toUInt()
        )

    fun readAll(buf: ByteBuffer, baseOffset: Int, count: Int): List<FieldAccessSiteResult> =
        List(count) { i -> read(buf, baseOffset + i * STRUCT_SIZE) }
}

private object TryItemWriter {
    const val STRUCT_SIZE = 12
    const val OFFSET_START_ADDR = 0
    const val OFFSET_INSN_COUNT = 4
    const val OFFSET_HANDLER_IDX = 8

    fun pack(items: List<TryItem>): ByteBuffer {
        val buf = ByteBuffer.allocateDirect(items.size * STRUCT_SIZE).order(ByteOrder.nativeOrder())
        items.forEachIndexed { index, item ->
            val base = index * STRUCT_SIZE
            buf.putInt(base + OFFSET_START_ADDR, (item.startAddr).toInt())
            buf.putShort(base + OFFSET_INSN_COUNT, (item.insnCount).toShort())
            buf.putInt(base + OFFSET_HANDLER_IDX, (item.handlerIdx).toInt())
        }
        return buf
    }

    fun writeAllToWire(wire: WireWriter, items: List<TryItem>) {
        val bytes = items.size * STRUCT_SIZE
        wire.writeRawBytes(bytes) { buf, baseOffset ->
            items.forEachIndexed { index, item ->
                val base = baseOffset + index * STRUCT_SIZE
                buf.putInt(base + OFFSET_START_ADDR, (item.startAddr).toInt())
                buf.putShort(base + OFFSET_INSN_COUNT, (item.insnCount).toShort())
                buf.putInt(base + OFFSET_HANDLER_IDX, (item.handlerIdx).toInt())
            }
        }
    }
}

